CREATE FUNCTION public.platform_company_directory() RETURNS TABLE(id uuid,name text,user_count bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.is_platform_owner() THEN RAISE EXCEPTION 'Platform-owner access required'; END IF; RETURN QUERY SELECT c.id,c.name,(SELECT count(*) FROM public.users u WHERE u.company_id=c.id) FROM public.companies c ORDER BY c.name; END $$;
REVOKE ALL ON FUNCTION public.platform_company_directory() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.platform_company_directory() TO authenticated;
CREATE FUNCTION public.guard_platform_values() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF TG_TABLE_NAME='platform_overrides' AND NEW.ends_at<=NEW.starts_at THEN RAISE EXCEPTION 'Promotion end must follow its start'; END IF;
 IF TG_TABLE_NAME='platform_products' THEN IF NEW.currency!~'^[A-Z]{3}$' THEN RAISE EXCEPTION 'Use a three-letter currency'; END IF; IF NEW.app_url<>'' AND NEW.app_url!~'^https://' THEN RAISE EXCEPTION 'Use a secure application URL'; END IF; END IF;
 RETURN NEW; END $$;
CREATE TRIGGER platform_value_guard BEFORE INSERT OR UPDATE ON public.platform_overrides FOR EACH ROW EXECUTE FUNCTION public.guard_platform_values(); CREATE TRIGGER platform_value_guard BEFORE INSERT OR UPDATE ON public.platform_products FOR EACH ROW EXECUTE FUNCTION public.guard_platform_values();
CREATE OR REPLACE FUNCTION public.guard_client_report() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.job_sheets; BEGIN
 IF TG_OP='UPDATE' AND (NEW.snapshot IS DISTINCT FROM OLD.snapshot OR NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.sheet_id IS DISTINCT FROM OLD.sheet_id OR NEW.token_hash IS DISTINCT FROM OLD.token_hash OR NEW.created_by IS DISTINCT FROM OLD.created_by) THEN RAISE EXCEPTION 'Reports are immutable; create a new link'; END IF;
 SELECT * INTO s FROM public.job_sheets WHERE id=NEW.sheet_id AND company_id=NEW.company_id AND status='completed'; IF NOT FOUND THEN RAISE EXCEPTION 'Report requires a completed company sheet'; END IF;
 IF TG_OP='INSERT' THEN NEW.snapshot=jsonb_build_object('number',s.jobsheet_number,'date',s.created_at::date,'company',(SELECT name FROM public.companies WHERE id=s.company_id),'logo',(SELECT logo_data FROM public.company_settings WHERE company_id=s.company_id),'template',(SELECT pdf_template FROM public.company_settings WHERE company_id=s.company_id),'client',(SELECT name FROM public.clients WHERE id=s.client_id),'address',(SELECT address FROM public.sites WHERE id=s.site_id),'equipment',concat_ws(' ',s.asset_type,s.asset_type_other,s.lift_model,s.serial_number),'fault',s.reported_fault,'work',s.repairs_performed,'notes',CASE WHEN s.special_notes_in_pdf THEN s.special_notes END,'technician',s.technician_name,'signed',s.signature_data IS NOT NULL,'checklist',s.checklist_snapshot,'checklist_values',s.checklist_values,'logs',(SELECT coalesce(jsonb_agg(jsonb_build_object('date',log_date,'in',time_in,'out',time_out,'travel',traveling_time_hours,'techs',technician_count)),'[]') FROM public.jobsheet_time_logs WHERE jobsheet_id=s.id),'parts',(SELECT coalesce(jsonb_agg(jsonb_build_object('description',part_description,'unit',unit,'quantity',quantity)),'[]') FROM public.jobsheet_parts WHERE jobsheet_id=s.id)); NEW.created_by=auth.uid(); END IF; RETURN NEW; END $$;
CREATE TABLE public.client_report_photos(report_id uuid NOT NULL REFERENCES public.client_reports(id) ON DELETE CASCADE,photo_path text NOT NULL,kind text NOT NULL DEFAULT 'other',PRIMARY KEY(report_id,photo_path));
GRANT ALL ON public.client_report_photos TO service_role; ALTER TABLE public.client_report_photos ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.capture_report_photos() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.client_report_photos(report_id,photo_path,kind) SELECT NEW.id,p->>'path',coalesce(p->>'kind','other') FROM public.job_sheets s CROSS JOIN LATERAL jsonb_array_elements(s.photo_paths) p WHERE s.id=NEW.sheet_id AND p->>'scope'='work' AND p->>'path' LIKE NEW.company_id::text||'/%'; RETURN NEW; END $$;
CREATE TRIGGER report_photos_snapshot AFTER INSERT ON public.client_reports FOR EACH ROW EXECUTE FUNCTION public.capture_report_photos();
CREATE FUNCTION public.guard_platform_conversion() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.platform_referrals; s public.platform_subscriptions; BEGIN SELECT * INTO r FROM public.platform_referrals WHERE id=NEW.referral_id; SELECT * INTO s FROM public.platform_subscriptions WHERE id=NEW.subscription_id; IF r.product_id<>s.product_id OR r.company_id=s.company_id THEN RAISE EXCEPTION 'Invalid product referral or self referral'; END IF; RETURN NEW; END $$;
CREATE TRIGGER conversion_guard BEFORE INSERT OR UPDATE ON public.platform_conversions FOR EACH ROW EXECUTE FUNCTION public.guard_platform_conversion();